function can_see_ticket(array $t): bool { $u=current_user(); if($u['role_code']==='CUSTOMER') return (int)$u['customer_id']===(int)$t['customer_id']; if(in_array($u['role_code'],['ADMIN','IT_LEAD','SALES'],true)) return true; return (int)($t['owner_user_id']??0)===(int)$u['id'] || (int)($t['assigned_user_id']??0)===(int)$u['id']; }
function notify_user(PDO $db,array $config,?int $userId,string $event,string $subject,string $body,?string $cc=null): void { if(!$userId)return; $s=$db->prepare('SELECT email FROM users WHERE id=?');$s->execute([$userId]);$to=$s->fetchColumn();if(!$to)return;$ok=mail_notice($config,(string)$to,$subject,$body,$cc);$s=$db->prepare('INSERT INTO email_logs(event_type,entity,entity_id,recipient,subject,status,error_message,created_at) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$event,'TICKET',null,$to,$subject,$ok?'SENT':'FAILED',$ok?null:'mail() failed',now()]); }
function page_header(string $title): void { global $user; ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> - MSP ITSM</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/app.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark bg-primary"><div class="container-fluid"><a class="navbar-brand fw-bold" href="?page=dashboard">MSP ITSM</a><div class="text-white small"><?=e($user['full_name'])?> · <?=e($user['role_name'])?> · <a class="text-white" href="?page=logout">Logout</a></div></nav><div class="container-fluid"><div class="row"><aside class="col-md-2 sidebar p-3"><a href="?page=dashboard">Dashboard</a><a href="?page=tickets">Tickets</a><a href="?page=contracts">Contracts</a><?php if($user['role_code']!=='CUSTOMER'):?><a href="?page=customers">Customers</a><?php endif;?></aside><main class="col-md-10 p-4"><?php foreach(flashes() as [$t,$m]):?><div class="alert alert-<?=$t?>"><?=e($m)?></div><?php endforeach; ?><h2 class="mb-4"><?=e($title)?></h2><?php }
function page_footer(): void { ?></main></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html><?php }

if($page==='dashboard'){
  page_header('Dashboard');
  $u=current_user(); $where='';$params=[]; if($u['role_code']==='CUSTOMER'){ $where='WHERE t.customer_id=?';$params[]=$u['customer_id']; } elseif($u['role_code']==='IT_SUPPORT'){ $where='WHERE t.assigned_user_id=?';$params[]=$u['id']; } elseif($u['role_code']==='IT_OWNER'){ $where='WHERE t.owner_user_id=?';$params[]=$u['id']; }
  $q=$db->prepare("SELECT COUNT(*) FROM tickets t $where");$q->execute($params);$total=(int)$q->fetchColumn();
  $q=$db->prepare("SELECT COUNT(*) FROM tickets t $where".($where?' AND ':' WHERE ')."t.status IN ('NEW','ASSIGNED','IN_PROGRESS','REOPENED')");$q->execute($params);$open=(int)$q->fetchColumn();
  $q=$db->prepare("SELECT COUNT(*) FROM tickets t $where".($where?' AND ':' WHERE ')."t.status='REOPENED'");$q->execute($params);$reopened=(int)$q->fetchColumn();
  $q=$db->prepare("SELECT COUNT(*) FROM tickets t $where".($where?' AND ':' WHERE ')."t.due_at IS NOT NULL AND t.due_at<NOW() AND t.status NOT IN ('CLOSED')");$q->execute($params);$breach=(int)$q->fetchColumn();
  ?><div class="row g-3"><div class="col-md-3"><div class="kpi"><span>Total Tickets</span><b><?=$total?></b></div></div><div class="col-md-3"><div class="kpi"><span>Open</span><b><?=$open?></b></div></div><div class="col-md-3"><div class="kpi"><span>Reopened</span><b class="text-danger"><?=$reopened?></b></div></div><div class="col-md-3"><div class="kpi"><span>SLA Breach</span><b class="text-danger"><?=$breach?></b></div></div></div><div class="d-flex justify-content-between align-items-center mt-4"><h5>Recent Tickets</h5><a class="btn btn-primary" href="?page=ticket_create">+ Create Ticket</a></div><?php $q=$db->prepare("SELECT t.*,c.name customer_name,s.name service_name,u.full_name assigned_name FROM tickets t JOIN customers c ON c.id=t.customer_id LEFT JOIN services s ON s.id=t.service_id LEFT JOIN users u ON u.id=t.assigned_user_id $where ORDER BY t.updated_at DESC LIMIT 10");$q->execute($params);$rows=$q->fetchAll();?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Ticket</th><th>Customer</th><th>Subject</th><th>Priority</th><th>Status</th><th>Assigned</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['ticket_no'])?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['subject'])?></td><td><?=priority_badge($r['priority'])?></td><td><?=ticket_badge($r['status'])?></td><td><?=e($r['assigned_name']??'-')?></td><td><a class="btn btn-sm btn-outline-primary" href="?page=ticket&id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();exit;
}

if($page==='tickets'){
  page_header('Ticket Management'); $u=current_user(); $where='';$params=[];
  if($u['role_code']==='CUSTOMER'){ $where='WHERE t.customer_id=?';$params[]=$u['customer_id']; } elseif($u['role_code']==='IT_SUPPORT'){ $where='WHERE t.assigned_user_id=?';$params[]=$u['id']; } elseif($u['role_code']==='IT_OWNER'){ $where='WHERE t.owner_user_id=?';$params[]=$u['id']; }
