  ?><div class="d-flex justify-content-between mb-3"><div><a class="btn btn-sm btn-outline-secondary" href="?page=tickets">All</a> <a class="btn btn-sm btn-outline-primary" href="?page=tickets&status=REOPENED">Reopened</a> <a class="btn btn-sm btn-outline-warning" href="?page=tickets&status=IN_PROGRESS">In Progress</a></div><a class="btn btn-primary" href="?page=ticket_create">+ Create Ticket</a></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>No</th><th>Customer</th><th>Subject</th><th>Priority</th><th>Status</th><th>Owner</th><th>Support</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="?page=ticket&id=<?=$r['id']?>"><?=e($r['ticket_no'])?></a></td><td><?=e($r['customer_name'])?></td><td><?=e($r['subject'])?></td><td><?=priority_badge($r['priority'])?></td><td><?=ticket_badge($r['status'])?></td><td><?=e($r['owner_name']??'-')?></td><td><?=e($r['assigned_name']??'-')?></td><td><?=e($r['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();exit;
}

if($page==='ticket_create'){
  page_header('Create Ticket'); $u=current_user();
  if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$customerId=$u['role_code']==='CUSTOMER'?(int)$u['customer_id']:(int)post('customer_id');$owner=null;if($customerId){$s=$db->prepare('SELECT owner_user_id FROM contracts WHERE customer_id=? AND status IN (\'ACTIVE\',\'EXPIRING\') ORDER BY end_date DESC LIMIT 1');$s->execute([$customerId]);$owner=$s->fetchColumn();}$id=TicketService::create($db,['customer_id'=>$customerId,'contract_id'=>(int)post('contract_id',0),'service_id'=>(int)post('service_id',0),'subject'=>trim((string)post('subject')),'description'=>trim((string)post('description')),'priority'=>post('priority','P3'),'owner_user_id'=>$owner?:null,'assigned_user_id'=>null,'created_by_user_id'=>$u['id']]);audit($db,$u['id'],'CREATE','TICKET',$id);flash('success','Ticket đã được tạo.');redirect('?page=ticket&id='.$id);}
  $customers=$db->query('SELECT id,name FROM customers WHERE status=\'ACTIVE\' ORDER BY name')->fetchAll();$services=$db->query('SELECT id,name FROM services WHERE is_active=1 ORDER BY name')->fetchAll();
  ?><form method="post" class="card border-0 shadow-sm"><div class="card-body"><?=csrf_field()?><div class="row g-3"><?php if($u['role_code']!=='CUSTOMER'):?><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select...</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-6"><label class="form-label">Service</label><select class="form-select" name="service_id"><option value="">Select...</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-9"><label class="form-label">Subject</label><input class="form-control" name="subject" required maxlength="255"></div><div class="col-md-3"><label class="form-label">Priority</label><select class="form-select" name="priority"><option>P3</option><option>P2</option><option>P1</option><option>P4</option></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="6" required></textarea></div></div></div><div class="card-footer bg-white"><button class="btn btn-primary">Create Ticket</button></div></form><?php page_footer();exit;
}

if($page==='ticket'){
  $id=(int)get('id');$s=$db->prepare('SELECT t.*,c.name customer_name,c.email customer_email,ct.contract_no,sv.name service_name,uo.full_name owner_name,ua.full_name assigned_name FROM tickets t JOIN customers c ON c.id=t.customer_id LEFT JOIN contracts ct ON ct.id=t.contract_id LEFT JOIN services sv ON sv.id=t.service_id LEFT JOIN users uo ON uo.id=t.owner_user_id LEFT JOIN users ua ON ua.id=t.assigned_user_id WHERE t.id=?');$s->execute([$id]);$t=$s->fetch();if(!$t||!can_see_ticket($t)){http_response_code(404);exit('Ticket not found');}
  page_header($t['ticket_no']);$users=$db->query("SELECT u.id,u.full_name,r.code FROM users u JOIN roles r ON r.id=u.role_id WHERE u.is_active=1 AND r.code IN ('IT_SUPPORT','IT_OWNER','IT_LEAD') ORDER BY u.full_name")->fetchAll();
  $s=$db->prepare('SELECT h.*,u.full_name FROM ticket_history h JOIN users u ON u.id=h.user_id WHERE h.ticket_id=? ORDER BY h.created_at');$s->execute([$id]);$history=$s->fetchAll();
  $s=$db->prepare('SELECT c.*,u.full_name FROM ticket_comments c JOIN users u ON u.id=c.user_id WHERE c.ticket_id=? AND (?<>\'CUSTOMER\' OR c.is_internal=0) ORDER BY c.created_at');$s->execute([$id,current_user()['role_code']]);$comments=$s->fetchAll();
  ?><div class="d-flex justify-content-between align-items-start"><div><div class="text-muted small"><?=e($t['customer_name'])?> · <?=e($t['contract_no']??'No contract')?> · <?=e($t['service_name']??'No service')?></div><h3><?=e($t['subject'])?></h3></div><div><?=priority_badge($t['priority'])?> <?=ticket_badge($t['status'])?></div></div><div class="row g-4 mt-1"><div class="col-lg-8"><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h6>Description</h6><div class="ticket-text"><?=nl2br(e($t['description']))?></div></div></div><div class="card shadow-sm border-0 mb-3"><div class="card-header bg-white fw-bold">Timeline</div><div class="card-body"><div class="timeline"><?php foreach($history as $h):?><div class="timeline-item"><div class="small text-muted"><?=e($h['created_at'])?> · <?=e($h['full_name'])?></div><div><b><?=e($h['event'])?></b> <?=e($h['value']??'')?></div><?php if($h['note']):?><div class="text-muted"><?=nl2br(e($h['note']))?></div><?php endif;?></div><?php endforeach;?></div></div></div><div class="card shadow-sm border-0"><div class="card-header bg-white fw-bold">Comments</div><div class="card-body"><?php foreach($comments as $c):?><div class="border-bottom py-2"><b><?=e($c['full_name'])?></b> <span class="text-muted small"><?=e($c['created_at'])?></span><div><?=nl2br(e($c['body']))?></div></div><?php endforeach;?><form method="post" action="?page=ticket_action" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="comment"><input type="hidden" name="id" value="<?=$id?>"><textarea class="form-control mb-2" name="note" required placeholder="Write an update..."></textarea><?php if(current_user()['role_code']!=='CUSTOMER'):?><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="internal" id="internal"><label class="form-check-label" for="internal">Internal note</label></div><?php endif;?><button class="btn btn-outline-primary">Add Comment</button></form></div></div></div><div class="col-lg-4"><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h6>Assignment</h6><p class="mb-1"><b>IT Owner:</b> <?=e($t['owner_name']??'-')?></p><p><b>Support:</b> <?=e($t['assigned_name']??'-')?></p><?php if(in_array(current_user()['role_code'],['ADMIN','IT_OWNER','IT_LEAD'],true)):?><form method="post" action="?page=ticket_action"><?=csrf_field()?><input type="hidden" name="action" value="assign"><input type="hidden" name="id" value="<?=$id?>"><select class="form-select mb-2" name="assigned_user_id"><option value="">Unassigned</option><?php foreach($users as $x): if($x['code']!=='IT_OWNER' && $x['code']!=='IT_LEAD'):?><option value="<?=$x['id']?>" <?=((int)$t['assigned_user_id']===(int)$x['id'])?'selected':''?>><?=e($x['full_name'])?></option><?php endif;endforeach;?></select><button class="btn btn-primary w-100">Assign Support</button></form><?php endif;?></div></div><div class="card shadow-sm border-0"><div class="card-body"><h6>Actions</h6><?php $role=current_user()['role_code'];?><div class="d-grid gap-2"><?php if($role==='CUSTOMER' && $t['status']==='RESOLVED'):?><form method="post" action="?page=ticket_action"><?=csrf_field()?><input type="hidden" name="action" value="reopen"><input type="hidden" name="id" value="<?=$id?>"><textarea class="form-control mb-2" name="note" required placeholder="Why is the issue not resolved?"></textarea><button class="btn btn-danger">Reopen Ticket</button></form><?php elseif($role!=='CUSTOMER'):?><form method="post" action="?page=ticket_action"><?=csrf_field()?><input type="hidden" name="action" value="start"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-warning">Start Work</button></form><form method="post" action="?page=ticket_action"><?=csrf_field()?><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-success">Resolve</button></form><?php elseif($t['status']==='RESOLVED'):?><form method="post" action="?page=ticket_action"><?=csrf_field()?><input type="hidden" name="action" value="close"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-success">Confirm & Close</button></form><?php endif;?></div></div></div></div><?php page_footer();exit;
}

if($page==='ticket_action'){
  verify_csrf();$id=(int)post('id');$s=$db->prepare('SELECT t.*,c.email customer_email,uo.email owner_email,ul.email lead_email,ua.email assigned_email FROM tickets t JOIN customers c ON c.id=t.customer_id LEFT JOIN users uo ON uo.id=t.owner_user_id LEFT JOIN users ul ON ul.id=(SELECT lead_user_id FROM contracts WHERE id=t.contract_id) LEFT JOIN users ua ON ua.id=t.assigned_user_id WHERE t.id=?');$s->execute([$id]);$t=$s->fetch();if(!$t)exit('Not found');$u=current_user();
  try{ $action=(string)post('action'); if($action==='assign'){require_role(['ADMIN','IT_OWNER','IT_LEAD']);$aid=post('assigned_user_id')?(int)post('assigned_user_id'):null;$s=$db->prepare('UPDATE tickets SET assigned_user_id=?,status=IF(status=\'NEW\',\'ASSIGNED\',status),updated_at=? WHERE id=?');$s->execute([$aid,now(),$id]);TicketService::history($db,$id,$u['id'],'ASSIGNED',$aid?'USER '.$aid:'UNASSIGNED',null);flash('success','Ticket assigned.');}
  elseif($action==='start'){require_role(['ADMIN','IT_SUPPORT','IT_OWNER','IT_LEAD']);TicketService::transition($db,$id,'IN_PROGRESS',$u['id']);flash('success','Ticket started.');}
  elseif($action==='resolve'){require_role(['ADMIN','IT_SUPPORT','IT_OWNER','IT_LEAD']);TicketService::transition($db,$id,'RESOLVED',$u['id'],(string)post('note','Resolved by IT Support'));flash('success','Ticket resolved.');}
  elseif($action==='close'){require_role(['CUSTOMER','ADMIN','IT_OWNER','IT_LEAD']);TicketService::transition($db,$id,'CLOSED',$u['id']);flash('success','Ticket closed.');}
  elseif($action==='reopen'){require_role(['CUSTOMER']);if((int)$u['customer_id']!==(int)$t['customer_id'])throw new RuntimeException('Forbidden');TicketService::transition($db,$id,'REOPENED',$u['id'],trim((string)post('note')));$subject='🚨 Ticket '.$t['ticket_no'].' đã được Customer REOPEN';$body="Ticket {$t['ticket_no']} của khách hàng đã được Reopen.\nLý do: ".post('note');$to=$t['owner_email']?:$t['lead_email'];$cc=implode(',',array_filter([$t['lead_email'],$t['assigned_email']]));if($to)mail_notice($config,$to,$subject,$body,$cc);flash('danger','Ticket đã được Reopen và cảnh báo IT phụ trách.');}
  elseif($action==='comment'){if(!can_see_ticket($t))throw new RuntimeException('Forbidden');TicketService::comment($db,$id,$u['id'],trim((string)post('note')),(bool)post('internal'));flash('success','Comment added.');}
  else throw new RuntimeException('Unknown action'); audit($db,$u['id'],'ACTION','TICKET',$id,['action'=>$action]);
  }catch(Throwable $e){flash('danger',$e->getMessage());} redirect('?page=ticket&id='.$id);
}

if($page==='contracts'){
  page_header('Contract Management');$u=current_user();$where='';$params=[];if($u['role_code']==='CUSTOMER'){$where='WHERE c.customer_id=?';$params[]=$u['customer_id'];}elseif($u['role_code']==='IT_OWNER'){$where='WHERE c.owner_user_id=?';$params[]=$u['id'];}$q=$db->prepare("SELECT c.*,cu.name customer_name,uo.full_name owner_name FROM contracts c JOIN customers cu ON cu.id=c.customer_id LEFT JOIN users uo ON uo.id=c.owner_user_id $where ORDER BY c.end_date ASC");$q->execute($params);$rows=$q->fetchAll();
  ?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Contract</th><th>Customer</th><th>Type</th><th>Start</th><th>End</th><th>Status</th><th>Alert 1</th><th>Alert 2</th><th>Alert 3</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$a=$db->prepare('SELECT alert_no,sent_at,status FROM contract_alerts WHERE contract_id=? ORDER BY alert_no');$a->execute([$r['id']]);$alerts=[];foreach($a->fetchAll() as $x){$alerts[(int)$x['alert_no']]=$x;}?><tr><td><?=e($r['contract_no'])?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['contract_type'])?></td><td><?=e($r['start_date'])?></td><td><?=e($r['end_date'])?></td><td><?=badge($r['status'],$r['status']==='ACTIVE'?'success':($r['status']==='EXPIRED'?'danger':'warning'))?></td><?php for($i=1;$i<=3;$i++):?><td><?php if(isset($alerts[$i])&&$alerts[$i]['sent_at']):?><?=badge(date('d/m/Y',strtotime($alerts[$i]['sent_at'])),'success')?><?php else:?><?=badge('Pending','secondary')?><?php endif;?></td><?php endfor;?><td><a class="btn btn-sm btn-outline-primary" href="?page=contract&id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();exit;
}

if($page==='contract'){
  $id=(int)get('id');$s=$db->prepare('SELECT c.*,cu.name customer_name,cu.email customer_email,uo.full_name owner_name,ul.full_name lead_name,us.full_name sales_name FROM contracts c JOIN customers cu ON cu.id=c.customer_id LEFT JOIN users uo ON uo.id=c.owner_user_id LEFT JOIN users ul ON ul.id=c.lead_user_id LEFT JOIN users us ON us.id=c.sales_user_id WHERE c.id=?');$s->execute([$id]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Contract not found');}if(current_user()['role_code']==='CUSTOMER'&&(int)current_user()['customer_id']!==(int)$c['customer_id']){http_response_code(403);exit('Forbidden');}page_header($c['contract_no']);$s=$db->prepare('SELECT r.*,a.sent_at,a.status,a.error_message FROM contract_alert_rules r LEFT JOIN contract_alerts a ON a.contract_id=r.contract_id AND a.alert_no=r.alert_no WHERE r.contract_id=? ORDER BY r.alert_no');$s->execute([$id]);$alerts=$s->fetchAll();$s=$db->prepare('SELECT s.name FROM contract_services cs JOIN services s ON s.id=cs.service_id WHERE cs.contract_id=? ORDER BY s.name');$s->execute([$id]);$services=$s->fetchAll();
  ?><div class="card shadow-sm border-0 mb-4"><div class="card-body"><div class="d-flex justify-content-between"><div><h3><?=e($c['contract_no'])?></h3><p class="text-muted mb-0"><?=e($c['customer_name'])?></p></div><?=badge($c['status'],$c['status']==='ACTIVE'?'success':($c['status']==='EXPIRED'?'danger':'warning'))?></div><hr><div class="row g-3"><div class="col-md-3"><b>Type</b><br><?=e($c['contract_type'])?></div><div class="col-md-3"><b>Start</b><br><?=e($c['start_date'])?></div><div class="col-md-3"><b>End</b><br><?=e($c['end_date'])?></div><div class="col-md-3"><b>Value</b><br><?=number_format((float)$c['value'],0,',','.')?></div><div class="col-md-3"><b>IT Owner</b><br><?=e($c['owner_name']??'-')?></div><div class="col-md-3"><b>IT Lead</b><br><?=e($c['lead_name']??'-')?></div><div class="col-md-3"><b>Sales</b><br><?=e($c['sales_name']??'-')?></div><div class="col-md-12"><b>Services</b><br><?php foreach($services as $sv):?><?=badge($sv['name'],'info')?> <?php endforeach;?></div></div></div></div><div class="card shadow-sm border-0"><div class="card-header bg-white fw-bold">Contract Alert History</div><div class="card-body"><table class="table"><thead><tr><th>Alert</th><th>Days Before</th><th>Sent At</th><th>Status</th><th>Error</th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td>#<?=e((string)$a['alert_no'])?></td><td><?=e((string)$a['days_before'])?> days</td><td><?=e($a['sent_at']??'-')?></td><td><?=badge($a['status']??'PENDING',($a['status']??'PENDING')==='SENT'?'success':(($a['status']??'PENDING')==='FAILED'?'danger':'secondary'))?></td><td><?=e($a['error_message']??'')?></td></tr><?php endforeach;?></tbody></table></div></div><?php page_footer();exit;
}

if($page==='customers'){
 require_role(['ADMIN','IT_LEAD','IT_OWNER','SALES']);page_header('Customers');$rows=$db->query("SELECT cu.*,COUNT(t.id) ticket_count,COUNT(DISTINCT c.id) contract_count FROM customers cu LEFT JOIN tickets t ON t.customer_id=cu.id LEFT JOIN contracts c ON c.customer_id=cu.id GROUP BY cu.id ORDER BY cu.name")->fetchAll();?><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Customer</th><th>Email</th><th>Contracts</th><th>Tickets</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e((string)$r['contract_count'])?></td><td><?=e((string)$r['ticket_count'])?></td><td><?=badge($r['status'],$r['status']==='ACTIVE'?'success':'secondary')?></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();exit;
}

http_response_code(404);echo 'Page not found';
